const base="/home/axel/LeanAlgebraicGeometry-Horizon";
const calls=[
  ["targets", `rg -n --glob '*.lean' 'Pic0FiniteStageOrbitAffine|FiniteStageOrbitAffine|finiteInAffine|FiniteInAffine' MainProjects/Algebraic-Jacobian-Challenge MainProjects/Algebraic-Jacobian-Challenge-Rebuild`],
  ["groupdefs", `rg -n --glob '*.lean' 'GroupScheme|group scheme|IsGroup|Grp_|multiplication|AlgebraicGroup|IsPreconnected|IrreducibleSpace|IsAlgClosed' MainProjects/Algebraic-Jacobian-Challenge MainProjects/Algebraic-Jacobian-Challenge-Rebuild`],
  ["manifests", `rg -n 'mathlib|rev|git' MainProjects/Algebraic-Jacobian-Challenge/lake-manifest.json MainProjects/Algebraic-Jacobian-Challenge-Rebuild/lake-manifest.json MainProjects/Algebraic-Jacobian-Challenge/lakefile.toml MainProjects/Algebraic-Jacobian-Challenge-Rebuild/lakefile.toml`],
  ["files", `rg --files MainProjects/Algebraic-Jacobian-Challenge MainProjects/Algebraic-Jacobian-Challenge-Rebuild | rg '(FiniteInAffine|Group|Pic0|Affine|lakefile|lake-manifest)'`]
];
const rs=await Promise.all(calls.map(async ([name,cmd])=>({name,...await tools.exec_command({cmd,workdir:base,yield_time_ms:30000,max_output_tokens:50000})})));
for(const r of rs) text(`--- ${r.name} ---\n${r.output}`);

const results = await Promise.all([
 tools.exec_command({cmd:"rg -n -i 'pic0FiniteStageFiniteInAffine|finite-stage.*affine|orbit.*affine|stable affine cover|FiniteInAffine' blueprint hgraph | sed -n '1,260p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:30000}),
 tools.exec_command({cmd:"rg --files | rg '(^|/)(blueprint|Blueprint)|\\.tex$' | sed -n '1,200p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:20000}),
 tools.exec_command({cmd:"rg -n 'AJCR\\.review-plan\\.p7-galois-descent\\.orbit-affine|Finite-level stable affine cover' .archon-horizon MainProjects 2>/dev/null | sed -n '1,160p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:30000})
]); for(let i=0;i<results.length;i++) text(`---${i+1}---\n${results[i].output}`);

const base="/home/axel/LeanAlgebraicGeometry-Horizon";
const qs=[
 ["group_fia", "rg -n --glob '*.lean' -i 'finiteInAffine.*group|group.*finiteInAffine|finite_in_affine.*group|finite type.*affine.*group|quasi.?compact.*affine.*group' MainProjects/Algebraic-Jacobian-Challenge MainProjects/Algebraic-Jacobian-Challenge-Rebuild"],
 ["group_theorems_original", "rg -n --glob '*.lean' '^(theorem|lemma|instance|def|structure|class) .*([Gg]roup|[Aa]ffine)|namespace GroupScheme|end GroupScheme' MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Albanese"],
 ["group_theorems_rebuild", "rg -n --glob '*.lean' '^(theorem|lemma|instance|def|structure|class) .*([Gg]roup|[Aa]ffine)|namespace GroupScheme|end GroupScheme' MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Descent MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard"],
 ["manifest", "sed -n '1,180p' MainProjects/Algebraic-Jacobian-Challenge-Rebuild/lake-manifest.json"],
 ["manifest_old", "sed -n '1,180p' MainProjects/Algebraic-Jacobian-Challenge/lake-manifest.json"]
];
const rs=await Promise.all(qs.map(async ([n,c])=>({n,...await tools.exec_command({cmd:c,workdir:base,yield_time_ms:30000,max_output_tokens:30000})})));
for(const r of rs) text(`--- ${r.n} ---\n${r.output}`);

const results = await Promise.all([
 tools.exec_command({cmd:"nl -ba blueprint/src/chapters/DivisorScheme.tex | sed -n '1660,1745p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:20000}),
 tools.exec_command({cmd:"sed -n '1,240p' hgraph/nodes/de91c1bb039f.md",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:20000}),
 tools.exec_command({cmd:"rg -n 'label:.*finite|orbit-affine|finite-stage' hgraph/nodes/*.md | sed -n '1,180p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:20000})
]); text("===== BLUEPRINT =====\n"+results[0].output); text("===== BP NODE =====\n"+results[1].output); text("===== MATCHES =====\n"+results[2].output);

const r = await tools.exec_command({
  cmd: "\"$HORIZON_BIN\" search \"every finite subset of a finite type group scheme over an arbitrary field is contained in an affine open\" --json -n 100",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
  yield_time_ms: 30000,
  max_output_tokens: 50000
});
text(JSON.stringify(r));

const results = await Promise.all([
 tools.exec_command({cmd:"lake env lean --help | sed -n '1,160p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:20000}),
 tools.exec_command({cmd:"command -v lean_verify || true; rg -n --hidden --glob '!*.jsonl' --glob '!*.lock' 'lean_verify' . .claude /home/axel/.archon-env/bin 2>/dev/null | sed -n '1,160p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:20000}),
 tools.exec_command({cmd:"find .lake/build/lib/lean/AlgebraicJacobian/Descent -maxdepth 1 -name 'FiniteInAffine.*' -printf '%f %s %TY-%Tm-%Td %TH:%TM:%TS\\n'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:10000})
]); text("===== LEAN HELP =====\n"+results[0].output); text("===== VERIFY TOOL =====\n"+results[1].output); text("===== ARTIFACTS =====\n"+results[2].output);

const ids = ["I-1482","I-0838","I-0492","I-1222"];
const results = await Promise.all(ids.map(id => tools.exec_command({
  cmd: `"${process.env.HORIZON_BIN || "/home/axel/.archon-env/bin/horizon"}" inbox show ${id} --no-mark-read --json | jq '{id,kind,status,body}'`,
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
  yield_time_ms: 30000,
  max_output_tokens: 12000
})));
for (const r of results) text(r.output);

const ids = ["I-1482","I-0838","I-0492","I-1222"];
const results = await Promise.all(ids.map(id => tools.exec_command({
  cmd: `"$HORIZON_BIN" inbox show ${id} --no-mark-read --json | jq '{id,kind,status,body}'`,
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
  yield_time_ms: 30000,
  max_output_tokens: 12000
})));
for (const r of results) text(r.output);

const results = await Promise.all([
  tools.exec_command({"cmd":"\"$HORIZON_BIN\" inbox show I-0492 --no-mark-read --json | jq -r '.body'","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":30000,"max_output_tokens":12000}),
  tools.exec_command({"cmd":"\"$HORIZON_BIN\" inbox show I-1222 --no-mark-read --json | jq -r '.body'","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":30000,"max_output_tokens":12000})
]);
for (const r of results) text(r.output);

const cmds = [
"\"$HORIZON_BIN\" search --name finiteInAffine -n 100 --json",
"\"$HORIZON_BIN\" search 'Every finite subset of a finite type group scheme over an arbitrary field lies in an affine open.' -n 30 --json",
"\"$HORIZON_BIN\" search 'A group scheme of finite type over a field is quasi-projective.' -n 30 --json"
];
const results = await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:30000,max_output_tokens:30000})));
for(let i=0;i<results.length;i++) text(`===== SEARCH ${i+1} =====\n${results[i].output}\nEXIT=${results[i].exit_code}`);

const base="/home/axel/LeanAlgebraicGeometry-Horizon";
const reads=[
 ["group_affine", "nl -ba MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Descent/GroupAffineOpen.lean | sed -n '1,230p'"],
 ["target", "nl -ba MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/Pic0FiniteStageOrbitAffine.lean | sed -n '1,150p'"],
 ["finite", "nl -ba MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Descent/FiniteInAffine.lean | sed -n '1,140p'"],
 ["qp_rebuild", "nl -ba MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Descent/QuasiProjectiveFiniteInAffine.lean | sed -n '1,105p'"],
 ["identity_tail", "nl -ba MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/IdentityComponent.lean | sed -n '1260,1390p'"]
];
const rs=await Promise.all(reads.map(async ([n,c])=>({n,...await tools.exec_command({cmd:c,workdir:base,yield_time_ms:30000,max_output_tokens:30000})})));
for(const r of rs) text(`--- ${r.n} ---\n${r.output}`);
